svg.script:
(function(){
  var z0=document.getElementById('lookZone'),svg=z0?z0.ownerSVGElement:null;
  if(!svg||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  var irises=svg.querySelectorAll('.iris'),droops=svg.querySelectorAll('.droop'),eyeG=svg.querySelectorAll('.eyeG');
  var dYaw=svg.getElementById('dYaw'),dPit=svg.getElementById('dPit'),YMAX=.26,PMAX=.13;
  var HCX=130.33,HCY=181.55,RX=14.72,RY=21.41;
  var EY=[[123.64,181.01],[136.91,181.06]];
  var HX=130.33+638,HY=180.88+60;
  var Y=0,Pt=0,tY=0,tP=0,ex=0,ey=0,tex=0,tey=0,active=false,raf=0;
  function clamp(v,m){return Math.max(-m,Math.min(m,v));}
  function toSvg(e){var p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());}
  function f(n){return n.toFixed(3);}
  function seg(arr,v){var i=0;while(arr.length-2>i){if(arr[i+1]>=v)break;i++;}var t=(v-arr[i])/(arr[i+1]-arr[i]);return [i,Math.max(0,Math.min(1,t))];}
  function show(){
    /* live head turn: the painted head is wrapped on an ellipsoid and rotated (yaw / pitch) */
    dYaw.setAttribute('scale',f(-2*Y*RX));dPit.setAttribute('scale',f(-2*Pt*RY));
    /* eyes ride with the turning face */
    for(var i=0;eyeG.length>i;i++){
      var nx=(EY[i][0]-HCX)/RX,ny=(EY[i][1]-HCY)/RY;
      var dx=(Math.sin(Math.asin(nx)+Y)-nx)*RX,dy=(Math.sin(Math.asin(ny)+Pt)-ny)*RY;

    }
    var tr='translate('+f(ex*1.75)+' '+f(ey>0?ey*.75:ey*.65)+')';
    var trc=tr.replace(/ /,'px,').replace(')','px)');
    Array.prototype.forEach.call(irises,function(el){el.style.transform=trc;});
    var dr=Math.max(0,ey)*.38;
    Array.prototype.forEach.call(droops,function(el){el.style.transform='scaleY('+f(dr)+')';});
  }
  var t0=performance.now();
  function reading(now){                         /* eyes read the laptop: slow sweep right, quick flick back */
    var c=((now-t0)/4700)%1;                    /* same slow speed both ways: left -> right -> left */
    var x=-.36*Math.cos(c*2*Math.PI);
    return [x,.65];
  }
  function frame(now){
    if(!active){var r=reading(now||performance.now());tex=r[0];tey=r[1];}
    Y+=(tY-Y)*.1;Pt+=(tP-Pt)*.1;ex+=(tex-ex)*.25;ey+=(tey-ey)*.25;
    show();
    var moving=Math.abs(tY-Y)+Math.abs(tP-Pt)+Math.abs(tex-ex)+Math.abs(tey-ey)>.0008;
    raf=requestAnimationFrame(frame);
  }
  function kick(){if(!raf)raf=requestAnimationFrame(frame);}
  z0.addEventListener('pointermove',function(e){
    var p=toSvg(e),dx=p.x-HX,dy=p.y-HY;
    tY=clamp(dx/140,1)*YMAX;tP=clamp(dy/150,1)*PMAX;
    tex=clamp(dx/50,1);tey=clamp(dy/55,1);
    active=true;kick();
  });
  z0.addEventListener('pointerleave',function(){active=false;tY=0;tP=0;kick();});
  svg.classList.add('js');show();kick();
})();
